// Generated by vibes-espmatter – OpenTelemetry: other features record gauges and counters
// (espm_otel.h); a task sends their latest values at a set interval as OTLP/HTTP JSON to an
// endpoint (OpenObserve, VictoriaMetrics, an OpenTelemetry Collector …). The endpoint is the OTLP
// base URL; `/v1/metrics` and `/v1/logs` are added (a URL already ending in one works too).
//
// Endpoint, Authorization header, interval and device metrics come from the build
// (MESP_OTEL_*) and can be changed in the admin dashboard (/api/otel, stored in NVS). A firmware
// built with other values than the last one overrides the device's settings, like Wi-Fi does.
//
// Timestamps need the wall clock, so nothing is recorded before SNTP synced (espm_ntp.cpp). Each
// push is a snapshot with its own timestamps. While the endpoint (or Wi-Fi) is down, snapshots are
// not kept; counters are cumulative totals, so energy readings still lose nothing.
//
// Metrics (MESP_OTEL_METRICS) and logs (MESP_OTEL_LOGS) can each be switched off. Logs: ESP-IDF
// log lines from the chosen level up are copied (they still go to the console) into a ring of
// their own and sent every MESP_OTEL_LOG_INTERVAL_S as OTLP logs to `<endpoint>/v1/logs` – with 0
// right away (a burst of lines in one request). An error line sends them about a second later (at
// most every ERROR_SEND_GAP_MS). Lines the push task logs itself never wake it, so its own
// messages can't make it send in a loop; they go with the next push. When the ring is full
// the oldest lines are dropped; lines logged before the clock was set get their time from the time
// since boot.
#include "espm_config.h"
#include "espm_ntp.h"
#include "espm_otel.h"

#include <cmath>
#include <cctype>
#include <cstdarg>
#include <cstdio>
#include <cstring>
#include <ctime>
#include <map>
#include <string>
#include <sys/time.h>

#include <esp_app_desc.h>
#include <esp_crt_bundle.h>
#include <esp_heap_caps.h>
#include <esp_http_client.h>
#include <esp_log.h>
#include <esp_timer.h>
#include <esp_wifi.h>
#include <nvs.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#include <freertos/task.h>

#if MESP_WEB
#include "espm_web.h"
#endif

static const char *TAG = "mesp_otel";

/** At most this many metrics (the system metrics, a heat pump, a few per Matter device …); more with PSRAM. */
#define MAX_METRICS_PSRAM 512
#define MAX_METRICS 192
/** Longest log line kept (longer ones are cut); formatted on the stack of the logging task. */
#define LOG_LINE_MAX 160
/** Log lines kept until sent: more with PSRAM. */
#define LOG_SLOTS_PSRAM 256
#define LOG_SLOTS 48
/** Push task notifications: the settings changed (send everything now), an error was logged. */
#define WAKE_SETTINGS 1
#define WAKE_LOG 2
/** Errors are sent right away, but at most this often. */
#define ERROR_SEND_GAP_MS 5000
/** Log interval 0: lines are sent this long after the first one (so a burst goes together), at
 * most every IMMEDIATE_GAP_MS; while the endpoint fails they are retried every LOG_RETRY_S. */
#define IMMEDIATE_DELAY_MS 200
#define IMMEDIATE_GAP_MS 1000
#define LOG_RETRY_S 10
/** Without Wi-Fi: how often to look whether it is back. */
#define WIFI_POLL_MS 2000
/** Log records per request, and requests per round. */
#define LOGS_PER_PUSH 48
#define LOG_PUSHES_PER_ROUND 4

/** A metric is identified by its name and attributes (`key=value;…`). */
struct metric_key_t {
    char name[48];
    char attrs[96];
    /** By name first: the data points of a name are next to each other. */
    bool operator<(const metric_key_t &o) const
    {
        const int c = strcmp(name, o.name);
        return c ? c < 0 : strcmp(attrs, o.attrs) < 0;
    }
};

struct metric_t {
    bool counter;
    char unit[12];
    double value;
    /** Counters: when the total started (first seen or last reset), esp_timer time. */
    int64_t start_us;
};

/** Runtime settings, stored in NVS as a blob – only append fields. */
struct settings_t {
    bool enabled;
    bool system;
    uint32_t interval_s;
    char endpoint[201];
    char auth[257];
    bool logs;
    /** Lowest level of the logs sent: 'E', 'W' or 'I'. */
    char log_level;
    bool metrics;
    uint32_t log_interval_s;
};

/** What the admin dashboard shows. */
struct status_t {
    const char *state; // "off", "clock" (waiting for the time), "wifi" (for Wi-Fi), "ok", "error"
    char error[64];
    time_t last_ok;
    char logs_error[64];
    time_t logs_last_ok;
    /** Wi-Fi is connected (as the push task saw it last). */
    bool online;
};

/** Allocates in PSRAM if the board has it: map entries are small, malloc would keep them internal. */
template <class T> struct prefer_psram {
    using value_type = T;
    prefer_psram() = default;
    template <class U> prefer_psram(const prefer_psram<U> &) {}
    T *allocate(size_t n)
    {
        void *p = heap_caps_malloc_prefer(n * sizeof(T), 2, MALLOC_CAP_SPIRAM, MALLOC_CAP_DEFAULT);
        if (!p) abort(); // like new without exceptions
        return (T *)p;
    }
    void deallocate(T *p, size_t) { heap_caps_free(p); }
    template <class U> bool operator==(const prefer_psram<U> &) const { return true; }
    template <class U> bool operator!=(const prefer_psram<U> &) const { return false; }
};

/** The latest value of each metric (about 200 bytes each). */
using metric_map_t =
    std::map<metric_key_t, metric_t, std::less<metric_key_t>, prefer_psram<std::pair<const metric_key_t, metric_t>>>;
static metric_map_t *s_metrics;
static settings_t s_settings;
static status_t s_status = {"clock", "", 0, "", 0};
/** Guards the metric table, the settings and the status. */
static SemaphoreHandle_t s_mutex;
static TaskHandle_t s_task;
static bool s_full_logged;

class Lock {
public:
    Lock() { xSemaphoreTake(s_mutex, portMAX_DELAY); }
    ~Lock() { xSemaphoreGive(s_mutex); }
};

// ---------------------------------------------------------------------------------------------
// Metric table
// ---------------------------------------------------------------------------------------------

static metric_key_t make_key(const char *name, const char *attrs)
{
    metric_key_t key;
    strlcpy(key.name, name, sizeof(key.name));
    strlcpy(key.attrs, attrs ? attrs : "", sizeof(key.attrs));
    return key;
}

static void record(const char *name, const char *unit, double value, const char *attrs, bool counter)
{
    if (!s_metrics || !name || !std::isfinite(value)) return;
    const metric_key_t key = make_key(name, attrs);
    Lock lock;
    auto it = s_metrics->find(key);
    if (it == s_metrics->end()) {
        const bool psram = heap_caps_get_total_size(MALLOC_CAP_SPIRAM) > 0;
        const size_t limit = psram ? MAX_METRICS_PSRAM : MAX_METRICS;
        if (s_metrics->size() >= limit) {
            if (!s_full_logged) ESP_LOGW(TAG, "More than %d metrics, dropping %s", (int)limit, name);
            s_full_logged = true;
            return;
        }
        it = s_metrics->emplace(key, metric_t{}).first;
        it->second.start_us = esp_timer_get_time();
    } else if (counter && value < it->second.value) {
        it->second.start_us = esp_timer_get_time();
    }
    metric_t &m = it->second;
    m.counter = counter;
    strlcpy(m.unit, unit ? unit : "", sizeof(m.unit));
    m.value = value;
}

void mesp_otel_gauge(const char *name, const char *unit, double value, const char *attrs)
{
    record(name, unit, value, attrs, false);
}

void mesp_otel_counter(const char *name, const char *unit, double total, const char *attrs)
{
    record(name, unit, total, attrs, true);
}

void mesp_otel_remove(const char *name, const char *attrs)
{
    if (!s_metrics || !name) return;
    const metric_key_t key = make_key(name, attrs);
    Lock lock;
    s_metrics->erase(key);
}

// ---------------------------------------------------------------------------------------------
// Log capture: a hook on esp_log copies lines into a ring the push task reads
// ---------------------------------------------------------------------------------------------

struct log_entry_t {
    /** esp_timer time of the line. */
    int64_t us;
    char text[LOG_LINE_MAX];
};

/** Slot i holds line number i % s_log_slots; s_log_read..s_log_write are the lines not sent. */
static log_entry_t *s_logs;
static uint32_t s_log_slots;
static uint32_t s_log_write, s_log_read, s_logs_dropped;
/** Guards the ring: a spinlock, as any task may log (also while holding s_mutex). */
static portMUX_TYPE s_log_mux = portMUX_INITIALIZER_UNLOCKED;
/** Lowest level captured ('E', 'W', 'I'); 0 = logs off. */
static volatile char s_log_level;
/** Log interval 0: every line wakes the push task. */
static volatile bool s_log_now;
static vprintf_like_t s_prev_vprintf;

/** E=1 … V=5, 0 = not a log level. */
static int level_rank(char level)
{
    switch (level) {
    case 'E': return 1;
    case 'W': return 2;
    case 'I': return 3;
    case 'D': return 4;
    case 'V': return 5;
    default: return 0;
    }
}

static int log_hook(const char *fmt, va_list args)
{
    va_list copy;
    va_copy(copy, args);
    const int ret = (s_prev_vprintf ? s_prev_vprintf : vprintf)(fmt, args);
    const char min = s_log_level;
    if (min && s_logs) {
        char line[LOG_LINE_MAX];
        vsnprintf(line, sizeof(line), fmt, copy);
        // Only esp_log lines ("W (1234) tag: …"), not stray printf output.
        const int rank = level_rank(line[0]);
        if (rank && rank <= level_rank(min) && line[1] == ' ' && line[2] == '(') {
            const int64_t now = esp_timer_get_time();
            portENTER_CRITICAL_SAFE(&s_log_mux);
            if (s_log_write - s_log_read == s_log_slots) {
                s_log_read++;
                s_logs_dropped++;
            }
            log_entry_t &e = s_logs[s_log_write % s_log_slots];
            e.us = now;
            memcpy(e.text, line, sizeof(line));
            s_log_write++;
            portEXIT_CRITICAL_SAFE(&s_log_mux);
            if ((rank == 1 || s_log_now) && s_task && xTaskGetCurrentTaskHandle() != s_task)
                xTaskNotify(s_task, WAKE_LOG, eSetBits);
        }
    }
    va_end(copy);
    return ret;
}

/** Switch capturing on or off; the hook stays installed once it is. */
static void apply_log_settings(const settings_t &cfg)
{
    const bool on = cfg.enabled && cfg.logs && level_rank(cfg.log_level);
    if (on && !s_logs) {
        const bool psram = heap_caps_get_total_size(MALLOC_CAP_SPIRAM) > 0;
        const uint32_t slots = psram ? LOG_SLOTS_PSRAM : LOG_SLOTS;
        auto *ring = (log_entry_t *)heap_caps_calloc_prefer(slots, sizeof(log_entry_t), 2,
                                                            MALLOC_CAP_SPIRAM, MALLOC_CAP_DEFAULT);
        if (!ring) {
            ESP_LOGE(TAG, "No memory for the log buffer");
            return;
        }
        s_log_slots = slots;
        s_logs = ring;
        s_prev_vprintf = esp_log_set_vprintf(log_hook);
    }
    s_log_now = cfg.log_interval_s == 0;
    s_log_level = on ? cfg.log_level : 0;
}

/** Copy up to `max` unsent lines; returns how many, `first` is the number of the first one. */
static size_t take_logs(log_entry_t *out, size_t max, uint32_t &first)
{
    portENTER_CRITICAL(&s_log_mux);
    first = s_log_read;
    size_t n = s_log_write - s_log_read;
    if (n > max) n = max;
    for (size_t i = 0; i < n; i++) out[i] = s_logs[(first + i) % s_log_slots];
    portEXIT_CRITICAL(&s_log_mux);
    return n;
}

/** Lines up to `end` are sent (or rejected for good). */
static void logs_done(uint32_t end)
{
    portENTER_CRITICAL(&s_log_mux);
    // Lines dropped meanwhile may already have moved the start past them.
    if ((int32_t)(end - s_log_read) > 0) s_log_read = end;
    portEXIT_CRITICAL(&s_log_mux);
}

// ---------------------------------------------------------------------------------------------
// OTLP JSON (opentelemetry/proto/metrics/v1, JSON mapping: 64-bit integers are strings)
// ---------------------------------------------------------------------------------------------

static void json_str(std::string &out, const char *v)
{
    out += '"';
    for (; *v; v++) {
        const unsigned char c = *v;
        if (c == '"' || c == '\\') {
            out += '\\';
            out += (char)c;
        } else if (c < 0x20) {
            char buf[8];
            snprintf(buf, sizeof(buf), "\\u%04x", c);
            out += buf;
        } else {
            out += (char)c;
        }
    }
    out += '"';
}

static void json_attr(std::string &out, const char *key, const char *value)
{
    out += "{\"key\":";
    json_str(out, key);
    out += ",\"value\":{\"stringValue\":";
    json_str(out, value);
    out += "}}";
}

/** `key=value;key=value` → attribute list (without the brackets). */
static void json_attrs(std::string &out, const char *attrs)
{
    char buf[sizeof(metric_key_t::attrs)];
    strlcpy(buf, attrs, sizeof(buf));
    bool first = true;
    char *save = nullptr;
    for (char *pair = strtok_r(buf, ";", &save); pair; pair = strtok_r(nullptr, ";", &save)) {
        char *eq = strchr(pair, '=');
        if (!eq || eq == pair) continue;
        *eq = '\0';
        if (!first) out += ',';
        first = false;
        json_attr(out, pair, eq + 1);
    }
}

static void json_ns(std::string &out, const char *key, int64_t ns)
{
    out += ",\"";
    out += key;
    out += "\":\"";
    out += std::to_string(ns);
    out += '"';
}

static int64_t now_ns()
{
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    return (int64_t)tv.tv_sec * 1000000000LL + (int64_t)tv.tv_usec * 1000LL;
}

/** `{"resource":{…}` – the device, the same for metrics and logs. */
static void json_resource(std::string &out)
{
    const esp_app_desc_t *app = esp_app_get_description();
    out += "{\"resource\":{\"attributes\":[";
    json_attr(out, "service.name", MESP_OTEL_SERVICE[0] ? MESP_OTEL_SERVICE : MESP_HOSTNAME);
    out += ',';
    json_attr(out, "service.version", app->version);
    out += ',';
    json_attr(out, "host.name", MESP_HOSTNAME);
    out += ',';
    json_attr(out, "vibes-espmatter.chip", MESP_ROLE);
    out += "]}";
}

/** All metrics as one OTLP export request; data points of a name are grouped. Empty if none. */
static std::string build_request()
{
    if (!s_metrics) return {};
    const int64_t now = now_ns();
    const int64_t boot_ns = now - esp_timer_get_time() * 1000LL;

    std::string out;
    out.reserve(4096);
    out += "{\"resourceMetrics\":[";
    json_resource(out);
    out += ",\"scopeMetrics\":[{\"scope\":{\"name\":\"vibes-espmatter\"},\"metrics\":[";

    Lock lock;
    if (s_metrics->empty()) return {};
    // In order of the names: a new metric begins where the name (or kind) changes.
    const metric_key_t *head = nullptr;
    bool head_counter = false;
    for (const auto &[key, m] : *s_metrics) {
        if (head && strcmp(head->name, key.name) == 0 && head_counter == m.counter) {
            out += ',';
        } else {
            if (head) out += "]}},";
            head = &key;
            head_counter = m.counter;
            out += "{\"name\":";
            json_str(out, key.name);
            out += ",\"unit\":";
            json_str(out, m.unit);
            out += m.counter ? ",\"sum\":{\"aggregationTemporality\":2,\"isMonotonic\":true,\"dataPoints\":["
                             : ",\"gauge\":{\"dataPoints\":[";
        }
        out += "{\"attributes\":[";
        json_attrs(out, key.attrs);
        out += ']';
        if (m.counter) json_ns(out, "startTimeUnixNano", boot_ns + m.start_us * 1000LL);
        json_ns(out, "timeUnixNano", now);
        char value[32];
        snprintf(value, sizeof(value), ",\"asDouble\":%.10g}", m.value);
        out += value;
    }
    out += "]}}";
    out += "]}]}]}";
    return out;
}

/** Log lines as one OTLP logs export request (opentelemetry/proto/logs/v1). */
static std::string build_logs_request(const log_entry_t *lines, size_t n)
{
    const int64_t now = now_ns();
    const int64_t boot_ns = now - esp_timer_get_time() * 1000LL;
    static const struct {
        int number;
        const char *text;
    } SEVERITY[] = {{9, "INFO"}, {17, "ERROR"}, {13, "WARN"}, {9, "INFO"}, {5, "DEBUG"}, {1, "TRACE"}};

    std::string out;
    out.reserve(n * 200 + 512);
    out += "{\"resourceLogs\":[";
    json_resource(out);
    out += ",\"scopeLogs\":[{\"scope\":{\"name\":\"vibes-espmatter\"},\"logRecords\":[";
    for (size_t i = 0; i < n; i++) {
        char text[LOG_LINE_MAX];
        memcpy(text, lines[i].text, sizeof(text));
        text[sizeof(text) - 1] = 0;
        for (size_t len = strlen(text); len && (text[len - 1] == '\n' || text[len - 1] == '\r');) text[--len] = 0;
        // "W (1234) tag: message" – the time in brackets is the console's, ours is exact.
        const char *tag = "";
        const char *body = text;
        if (char *close = strstr(text, ") ")) {
            tag = close + 2;
            if (char *colon = strstr(close + 2, ": ")) {
                *colon = 0;
                body = colon + 2;
            } else {
                body = tag;
                tag = "";
            }
        }
        const auto &sev = SEVERITY[level_rank(text[0])];
        if (i) out += ',';
        out += "{\"timeUnixNano\":\"";
        out += std::to_string(boot_ns + lines[i].us * 1000LL);
        out += '"';
        json_ns(out, "observedTimeUnixNano", now);
        out += ",\"severityNumber\":";
        out += std::to_string(sev.number);
        out += ",\"severityText\":";
        json_str(out, sev.text);
        out += ",\"body\":{\"stringValue\":";
        json_str(out, body);
        out += "},\"attributes\":[";
        if (tag[0]) json_attr(out, "log.tag", tag);
        out += "]}";
    }
    out += "]}]}]}";
    return out;
}

// ---------------------------------------------------------------------------------------------
// Push task
// ---------------------------------------------------------------------------------------------

enum push_result_t { PUSH_OK, PUSH_RETRY, PUSH_REJECTED };

/** The push task's copy of the settings, taken at the start of each round. */
static settings_t s_cfg;
/** Room for the endpoint and the path added to it. */
#define URL_MAX (sizeof(settings_t::endpoint) + 12)
/** Where the metrics go: the endpoint with /v1/metrics. */
static char s_metrics_url[URL_MAX];

static void set_status(const char *state, const char *error = "")
{
    Lock lock;
    s_status.state = state;
    strlcpy(s_status.error, error, sizeof(s_status.error));
    if (strcmp(state, "ok") == 0) s_status.last_ok = time(nullptr);
}

static void set_logs_status(const char *error)
{
    Lock lock;
    strlcpy(s_status.logs_error, error, sizeof(s_status.logs_error));
    if (!error[0]) s_status.logs_last_ok = time(nullptr);
}

/** The status of the metrics or (`logs`) of the logs. */
static void report(bool logs, const char *error)
{
    if (logs)
        set_logs_status(error);
    else
        set_status(error[0] ? "error" : "ok", error);
}

/**
 * The URL of a signal ("metrics", "logs"): the base URL with /v1/<signal>. A trailing slash or
 * /v1/metrics, /v1/logs (a full URL as set before) is taken off first.
 */
static void signal_url(const char *endpoint, const char *signal, char *out)
{
    size_t len = strlen(endpoint);
    while (len && endpoint[len - 1] == '/') len--;
    for (const char *path : {"/v1/metrics", "/v1/logs"}) {
        const size_t n = strlen(path);
        if (len >= n && strncmp(endpoint + len - n, path, n) == 0) {
            len -= n;
            break;
        }
    }
    snprintf(out, URL_MAX, "%.*s/v1/%s", (int)len, endpoint, signal);
}

/** POST the request. PUSH_RETRY: try again later (no connection, server error, rate limit). */
static push_result_t push(const char *url, const char *body, size_t len, bool logs = false)
{
    esp_http_client_config_t config = {};
    config.url = url;
    config.method = HTTP_METHOD_POST;
    config.timeout_ms = 10000;
    if (strncmp(url, "https:", 6) == 0) config.crt_bundle_attach = esp_crt_bundle_attach;
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (!client) {
        report(logs, "invalid endpoint URL");
        return PUSH_RETRY;
    }
    esp_http_client_set_header(client, "Content-Type", "application/json");
    if (s_cfg.auth[0]) esp_http_client_set_header(client, "Authorization", s_cfg.auth);
    esp_http_client_set_post_field(client, body, len);
    esp_err_t err = esp_http_client_perform(client);
    const int status = esp_http_client_get_status_code(client);
    esp_http_client_cleanup(client);
    char msg[64];
    // On a 401 esp_http_client tries its own Basic/Digest login and fails with
    // ESP_ERR_NOT_SUPPORTED (e.g. "Bearer" or no WWW-Authenticate) – the server did answer.
    const char *what = logs ? "Log push" : "Push";
    if (err != ESP_OK && status != 401) {
        ESP_LOGW(TAG, "%s failed: %s", what, esp_err_to_name(err));
        snprintf(msg, sizeof(msg), "not reachable (%s)", esp_err_to_name(err));
        report(logs, msg);
        return PUSH_RETRY;
    }
    if (status >= 200 && status < 300) {
        report(logs, "");
        return PUSH_OK;
    }
    ESP_LOGW(TAG, "%s rejected: HTTP %d", what, status);
    snprintf(msg, sizeof(msg), "HTTP %d%s", status,
             status == 401 || status == 403 ? " – check the Authorization header"
             : logs && status == 404        ? " – does the backend take OTLP logs?"
                                            : "");
    report(logs, msg);
    return status >= 400 && status < 500 && status != 408 && status != 429 ? PUSH_REJECTED : PUSH_RETRY;
}

static void record_system(const wifi_ap_record_t &ap)
{
    mesp_otel_counter("device.uptime", "s", esp_timer_get_time() / 1000000);
    mesp_otel_gauge("device.memory.free", "By", heap_caps_get_free_size(MALLOC_CAP_INTERNAL));
    mesp_otel_gauge("device.memory.free.min", "By", heap_caps_get_minimum_free_size(MALLOC_CAP_INTERNAL));
    if (heap_caps_get_total_size(MALLOC_CAP_SPIRAM))
        mesp_otel_gauge("device.psram.free", "By", heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    mesp_otel_gauge("device.wifi.rssi", "dBm", ap.rssi);
}

/** Last log push: whether it went through, and when (ticks). */
static bool s_logs_ok;
static TickType_t s_logs_sent_at;

/** Send the captured log lines, a few requests per round; they wait in the ring when it fails. */
static void send_logs()
{
    if (!s_logs) return;
    char url[URL_MAX];
    signal_url(s_cfg.endpoint, "logs", url);
    auto *batch = (log_entry_t *)malloc(LOGS_PER_PUSH * sizeof(log_entry_t));
    if (!batch) return;
    bool ok = true;
    for (int round = 0; round < LOG_PUSHES_PER_ROUND; round++) {
        uint32_t first;
        const size_t n = take_logs(batch, LOGS_PER_PUSH, first);
        if (!n) break;
        const std::string body = build_logs_request(batch, n);
        if (push(url, body.data(), body.size(), true) == PUSH_RETRY) {
            ok = false;
            break;
        }
        logs_done(first + n); // sent, or rejected for good
    }
    free(batch);
    s_logs_ok = ok;
    s_logs_sent_at = xTaskGetTickCount();
}

/** Whether the metrics endpoint took the last push (for logging the changes only). */
static bool s_metrics_ok;

/** Record the device metrics and send all metrics; `ap`: nullptr while Wi-Fi is down. */
static void send_metrics(const wifi_ap_record_t *ap)
{
    if (!ap) {
        set_status("wifi");
        s_metrics_ok = false;
        return;
    }
    if (s_cfg.system) record_system(*ap);
    const std::string body = build_request();
    if (body.empty()) return;
    const bool reachable = push(s_metrics_url, body.data(), body.size()) != PUSH_RETRY;
    if (reachable && !s_metrics_ok) ESP_LOGI(TAG, "Sending metrics to %s", s_metrics_url);
    s_metrics_ok = reachable;
}

/** Wait until `due` or a notification; returns its WAKE_* bits (0: due). */
static uint32_t wait_until(TickType_t due)
{
    const TickType_t now = xTaskGetTickCount();
    uint32_t bits = 0;
    if ((int32_t)(due - now) > 0) xTaskNotifyWait(0, UINT32_MAX, &bits, due - now);
    return bits;
}

static bool is_due(TickType_t due, TickType_t now)
{
    return (int32_t)(now - due) >= 0;
}

static void push_task(void *)
{
    // Metrics and logs each on their own schedule; 0 = right away.
    TickType_t next_metrics = 0, next_logs = 0;
    bool was_online = false;
    for (;;) {
        {
            Lock lock;
            s_cfg = s_settings;
        }
        signal_url(s_cfg.endpoint, "metrics", s_metrics_url);
        TickType_t now = xTaskGetTickCount();
        if (!s_cfg.enabled || !s_cfg.endpoint[0]) {
            set_status("off");
            s_metrics_ok = false;
            wait_until(now + pdMS_TO_TICKS(60000));
            next_metrics = next_logs = xTaskGetTickCount();
            continue;
        }
        if (!mesp_time_synced()) {
            set_status("clock");
            wait_until(now + pdMS_TO_TICKS(5000));
            continue;
        }
        // The clock survives a restart: the first round may come before Wi-Fi is up.
        wifi_ap_record_t ap;
        const bool online = esp_wifi_sta_get_ap_info(&ap) == ESP_OK;
        {
            Lock lock;
            s_status.online = online;
        }
        // (Back) online: send right away instead of at the next interval.
        if (online && !was_online) next_metrics = next_logs = now;
        was_online = online;
        if (!s_cfg.metrics) {
            set_status("off");
        } else if (is_due(next_metrics, now)) {
            send_metrics(online ? &ap : nullptr);
            next_metrics = now + pdMS_TO_TICKS(s_cfg.interval_s * 1000);
        }
        // Offline the lines wait in the ring.
        if (s_cfg.logs && online && is_due(next_logs, now)) {
            send_logs();
            next_logs = now + pdMS_TO_TICKS((s_cfg.log_interval_s ? s_cfg.log_interval_s : LOG_RETRY_S) * 1000);
        }

        TickType_t wake = now + pdMS_TO_TICKS(60000);
        if (s_cfg.metrics) wake = next_metrics;
        if (s_cfg.logs && (!s_cfg.metrics || (int32_t)(next_logs - wake) < 0)) wake = next_logs;
        // Offline: look for Wi-Fi every few seconds (due logs wait for it).
        if (!online) wake = now + pdMS_TO_TICKS(WIFI_POLL_MS);
        const uint32_t bits = wait_until(wake);
        if (bits & WAKE_SETTINGS) {
            next_metrics = next_logs = xTaskGetTickCount();
        } else if ((bits & WAKE_LOG) && s_cfg.logs) {
            // Let the lines around it come in too. Not while the endpoint fails (that waits for
            // the retry), and not more often than every ERROR_SEND_GAP_MS / IMMEDIATE_GAP_MS.
            const bool immediate = s_cfg.log_interval_s == 0;
            vTaskDelay(pdMS_TO_TICKS(immediate ? IMMEDIATE_DELAY_MS : 1000));
            now = xTaskGetTickCount();
            const TickType_t gap = pdMS_TO_TICKS(immediate ? IMMEDIATE_GAP_MS : ERROR_SEND_GAP_MS);
            if (s_logs_ok && is_due(s_logs_sent_at + gap, now)) next_logs = now;
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------------------------

#define MIN_INTERVAL_S 10
#define MAX_INTERVAL_S 3600

/** FNV-1a of the build's settings: tells whether a newly flashed firmware brings other ones. */
static uint32_t build_settings_hash()
{
    char interval[48];
    snprintf(interval, sizeof(interval), "%d/%d/%d/%d/%s/%d", (int)MESP_OTEL_METRICS, (int)MESP_OTEL_INTERVAL_S,
             (int)MESP_OTEL_SYSTEM, (int)MESP_OTEL_LOGS, MESP_OTEL_LOG_LEVEL, (int)MESP_OTEL_LOG_INTERVAL_S);
    uint32_t h = 2166136261u;
    for (const char *s : {MESP_OTEL_ENDPOINT, "\n", MESP_OTEL_AUTH, "\n", (const char *)interval}) {
        for (; *s; s++) h = (h ^ (uint8_t)*s) * 16777619u;
    }
    return h;
}

/** The device's settings, or the build's when it brings other ones than last time. */
static void load_settings()
{
    settings_t build = {};
    build.enabled = MESP_OTEL_ENDPOINT[0] != 0;
    build.system = MESP_OTEL_SYSTEM;
    build.interval_s = MESP_OTEL_INTERVAL_S;
    strlcpy(build.endpoint, MESP_OTEL_ENDPOINT, sizeof(build.endpoint));
    strlcpy(build.auth, MESP_OTEL_AUTH, sizeof(build.auth));
    build.logs = MESP_OTEL_LOGS;
    build.log_level = MESP_OTEL_LOG_LEVEL[0];
    build.metrics = MESP_OTEL_METRICS;
    build.log_interval_s = MESP_OTEL_LOG_INTERVAL_S;
    s_settings = build;

    nvs_handle_t h;
    if (nvs_open("mesp_otel", NVS_READWRITE, &h) != ESP_OK) return;
    uint32_t applied = 0;
    const uint32_t hash = build_settings_hash();
    settings_t stored = {};
    size_t len = sizeof(stored);
    if (nvs_get_u32(h, "build", &applied) == ESP_OK && applied == hash &&
        nvs_get_blob(h, "settings", &stored, &len) == ESP_OK && len == sizeof(stored)) {
        stored.endpoint[sizeof(stored.endpoint) - 1] = 0;
        stored.auth[sizeof(stored.auth) - 1] = 0;
        if (stored.interval_s < MIN_INTERVAL_S || stored.interval_s > MAX_INTERVAL_S) stored.interval_s = build.interval_s;
        if (level_rank(stored.log_level) < 1 || level_rank(stored.log_level) > 3) stored.log_level = build.log_level;
        if (stored.log_interval_s > MAX_INTERVAL_S) stored.log_interval_s = build.log_interval_s;
        s_settings = stored;
    } else {
        ESP_LOGI(TAG, "Using the OpenTelemetry settings of this firmware");
        nvs_erase_key(h, "settings");
        nvs_set_u32(h, "build", hash);
        nvs_commit(h);
    }
    nvs_close(h);
}

static bool save_settings(const settings_t &next)
{
    nvs_handle_t h;
    if (nvs_open("mesp_otel", NVS_READWRITE, &h) != ESP_OK) return false;
    const bool ok = nvs_set_blob(h, "settings", &next, sizeof(next)) == ESP_OK && nvs_commit(h) == ESP_OK;
    nvs_close(h);
    return ok;
}

// ---------------------------------------------------------------------------------------------
// Admin dashboard: GET/POST /api/otel
// ---------------------------------------------------------------------------------------------

#if MESP_WEB
static const char *level_name(char level)
{
    return level == 'E' ? "error" : level == 'I' ? "info" : "warn";
}

/** Settings (without the Authorization header itself) and how sending goes. */
static esp_err_t send_settings(httpd_req_t *req)
{
    settings_t cfg;
    status_t st;
    {
        Lock lock;
        cfg = s_settings;
        st = s_status;
    }
    Json j;
    j.obj().key("enabled").boolean(cfg.enabled).key("endpoint").str(cfg.endpoint);
    j.key("authSet").boolean(cfg.auth[0] != 0).key("interval").num(cfg.interval_s);
    j.key("system").boolean(cfg.system);
    j.key("metrics").boolean(cfg.metrics).key("logs").boolean(cfg.logs);
    j.key("logLevel").str(level_name(cfg.log_level)).key("logInterval").num(cfg.log_interval_s);
    j.key("status").obj().key("state").str(st.state).key("error").str(st.error).key("online").boolean(st.online);
    j.key("lastOk").num((long long)st.last_ok);
    uint32_t log_waiting, log_dropped;
    portENTER_CRITICAL(&s_log_mux);
    log_waiting = s_log_write - s_log_read;
    log_dropped = s_logs_dropped;
    portEXIT_CRITICAL(&s_log_mux);
    j.key("logsError").str(st.logs_error).key("logsLastOk").num((long long)st.logs_last_ok);
    j.key("logsWaiting").num(log_waiting).key("logsDropped").num(log_dropped).end_obj();
    j.end_obj();
    return mesp_web_send_json(req, j.out());
}

static esp_err_t otel_get(httpd_req_t *req)
{
    if (!mesp_web_require(req, MESP_ROLE_ADMIN)) return ESP_OK;
    return send_settings(req);
}

/** Empty, or an http(s) URL that fits. */
static bool valid_url(const std::string &v, size_t size)
{
    const bool http = v.rfind("http://", 0) == 0 || v.rfind("https://", 0) == 0;
    return v.empty() || (http && v.size() < size && v.find_first_of(" \t\r\n") == std::string::npos);
}

static bool is_true(const std::string &v)
{
    return v == "true" || v == "1" || v == "on";
}

/** Change settings; fields that aren't sent stay. `auth` replaces the header (empty: none). */
static esp_err_t otel_post(httpd_req_t *req)
{
    if (!mesp_web_require(req, MESP_ROLE_ADMIN)) return ESP_OK;
    std::string body, v;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    settings_t next;
    {
        Lock lock;
        next = s_settings;
    }
    if (mesp_web_param(body, "endpoint", v)) {
        if (!valid_url(v, sizeof(next.endpoint)))
            return mesp_web_send_error(req, "400 Bad Request", "the endpoint must be an http:// or https:// URL");
        strlcpy(next.endpoint, v.c_str(), sizeof(next.endpoint));
    }
    if (mesp_web_param(body, "auth", v)) {
        if (v.size() >= sizeof(next.auth) || v.find_first_of("\r\n") != std::string::npos)
            return mesp_web_send_error(req, "400 Bad Request", "invalid Authorization header");
        strlcpy(next.auth, v.c_str(), sizeof(next.auth));
    }
    if (mesp_web_param(body, "interval", v)) {
        const long secs = strtol(v.c_str(), nullptr, 10);
        if (secs < MIN_INTERVAL_S || secs > MAX_INTERVAL_S)
            return mesp_web_send_error(req, "400 Bad Request", "the interval must be 10 to 3600 seconds");
        next.interval_s = secs;
    }
    if (mesp_web_param(body, "logInterval", v)) {
        const long secs = strtol(v.c_str(), nullptr, 10);
        if (secs < 0 || secs > MAX_INTERVAL_S)
            return mesp_web_send_error(req, "400 Bad Request", "the log interval must be 0 (right away) to 3600 seconds");
        next.log_interval_s = secs;
    }
    if (mesp_web_param(body, "metrics", v)) next.metrics = is_true(v);
    if (mesp_web_param(body, "system", v)) next.system = is_true(v);
    if (mesp_web_param(body, "enabled", v)) next.enabled = is_true(v);
    if (mesp_web_param(body, "logs", v)) next.logs = is_true(v);
    if (mesp_web_param(body, "logLevel", v)) {
        if (v != "error" && v != "warn" && v != "info")
            return mesp_web_send_error(req, "400 Bad Request", "the log level must be error, warn or info");
        next.log_level = (char)toupper(v[0]);
    }
    if (next.enabled && !next.endpoint[0])
        return mesp_web_send_error(req, "400 Bad Request", "set the endpoint first");
    if (!save_settings(next)) return mesp_web_send_error(req, "500 Internal Server Error", "couldn't save the settings");
    {
        Lock lock;
        s_settings = next;
        s_status = {next.enabled ? "clock" : "off", "", s_status.last_ok, "", s_status.logs_last_ok};
    }
    apply_log_settings(next);
    ESP_LOGI(TAG, "Settings changed: %s, metrics %s, logs %s", next.enabled ? next.endpoint : "off",
             next.metrics ? "on" : "off", next.logs ? "on" : "off");
    if (s_task) xTaskNotify(s_task, WAKE_SETTINGS, eSetBits); // send right away
    return send_settings(req);
}

void mesp_otel_register_web()
{
    mesp_web_add("/api/otel", HTTP_GET, otel_get);
    mesp_web_add("/api/otel", HTTP_POST, otel_post);
}
#endif

// ---------------------------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------------------------

void mesp_otel_init()
{
    s_mutex = xSemaphoreCreateMutex();
    s_metrics = new metric_map_t();
    load_settings();
    // Now, so the logs of the start are kept too.
    apply_log_settings(s_settings);
}

void mesp_otel_start()
{
    xTaskCreate(push_task, "mesp_otel", 8192, nullptr, 3, &s_task);
}
